use super::*;
use protocol::mutation::retained::{RetainedMutationLeaf,RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};
use semio_framework_value::{DslValue,ToValue,retirement::RetireOwned};
use semio_framework_value_native_owned::NativeReceive;
#[path="../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{receive,source,grant,observe,drain,denied_axes,project_record,central_fragment,assert_portable_value};
#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
#[value(tag="mutation",rename_all="camelCase")]
enum Operation{AddOutputVariable(crate::AddOutputVariable),RemoveOutputVariable(crate::RemoveOutputVariable)}
impl From<crate::AddOutputVariable> for Operation{fn from(v:crate::AddOutputVariable)->Self{Self::AddOutputVariable(v)}}
impl From<crate::RemoveOutputVariable> for Operation{fn from(v:crate::RemoveOutputVariable)->Self{Self::RemoveOutputVariable(v)}}
impl protocol::Mutation<EnergyModelSnapshot> for Operation{type Diff=EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("original registration tests invoke the actual schema leaf")}}
fn run<L>(case:&serde_json::Value,law:&serde_json::Value)where L:RetainedMutationLeaf<EnergyModelSnapshot,Operation>+NativeReceive<DslValue>+RetireOwned+Sync{
 let body=law["bodyBytes"].as_u64().unwrap()as usize;let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut document=document["document"].take();document["model"]=helpers::corpus()["model"].clone();document["model"]["output_variables"]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let input=source(receive::<L>(&case["payload"]));let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<Operation>::default();let context=RetainedMutationCloseContext{mutations:&factory};
 for cut in std::iter::once(None).chain(law["cancelCuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=L::Preparation::new();let mut ready=false;for turn in 0..cut.unwrap_or(1000000){let d=owner.decision_demand(input.borrow(),original.borrow(),body).unwrap();assert!(d.copy_bytes<=body&&d.capacity_bytes<=law["capacityBytes"].as_u64().unwrap()as usize);let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||owner.decide(input.borrow(),original.borrow(),body,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.decision_demand(input.borrow(),original.borrow(),body).unwrap(),d)}let(step,heap)=observe(||owner.decide(input.borrow(),original.borrow(),body,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedMutationAdvance::Ready(_)){ready=true;break}assert!(turn<999999,"{} registration decision stalled",case["id"])}
 let mut diff=None;let mut inverse=None;if cut.is_none(){assert!(ready);match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert_ne!(case["outcome"],"changed");assert_eq!(messages.len(),1);let code=match case["outcome"].as_str().unwrap(){"invalid"=>"mutation.invariant","duplicate"=>"mutation.duplicate-id",_=>"mutation.target-missing"};assert_eq!(messages[0].code.0.as_str(),code);assert_eq!(messages[0].target,[case["payload"]["name"].as_str().unwrap(),case["payload"]["key"].as_str().unwrap()]);drain(messages)},RetainedMutationDecision::Admitted(value,messages)=>{assert_eq!(case["outcome"],"changed");assert!(messages.is_empty());drain(messages);let value=source(value);for turn in 0..1000000{let d=owner.inverse_demand(input.borrow(),original.borrow(),value.borrow(),body).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),body,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0))}let(step,heap)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),body,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedMutationAdvance::Ready(_)){break}assert!(turn<999999,"registration inverse stalled")}
 let operations=owner.take_inverse();assert_eq!(operations.len(),1);let expected=if case["insert"]==true{serde_json::json!({"mutation":"removeOutputVariable","name":case["payload"]["name"],"key":case["payload"]["key"]})}else{let mut v=case["inverse"].clone();v["mutation"]=serde_json::json!("addOutputVariable");v};assert_portable_value(operations[0].to_value(),&expected);let mut post=project_record(original.borrow());assert!(central_fragment(&value,original.borrow(),&mut post));assert_portable_value(post.model.outputs.get().output_variables.to_value(),&case["after"]);macro_rules! unchanged{($($branch:ident),*)=>{$(assert_eq!(post.model.$branch.identity(),original.borrow().get().model.$branch.identity());)*}}unchanged!(identity,geometry,materials,loads,controls,systems,generation);drain(post);inverse=Some(operations);diff=Some(value);}}}
 owner.begin_close();for turn in 0..1000000{if owner.terminal_is_empty(){break}let d=owner.close_demand(context,body).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.close_demand(context,body).unwrap(),d)}let(step,heap)=observe(||owner.close_step(context,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<999999,"{} registration closure stalled at {d:?}",case["id"])}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(v)=inverse{drain(v)}if let Some(v)=diff{drain(v)}}drain(input);drain(original)
}
#[test]fn output_variable_native_events_preserve_composite_identity_rank_inverse_and_every_cancelled_owner(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){if case["insert"]==true{run::<crate::AddOutputVariable>(case,&law)}else{run::<crate::RemoveOutputVariable>(case,&law)}}}
#[test]fn output_variable_wide_original_strings_remain_fragmented_and_keep_the_complete_inverse(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let text="α🙂".repeat(law["wideRepeat"].as_u64().unwrap()as usize);let mut case=law["cases"][4].clone();case["payload"]["name"]=serde_json::json!(text);case["before"][0]["name"]=serde_json::json!(text);case["inverse"]["name"]=serde_json::json!(text);run::<crate::RemoveOutputVariable>(&case,&law)}
